entries[433828] = { ["name"] = "Blutschmaus", ["text"] = "Sofort\nDie Bestie saugt Spielercharakteren das Blut aus, was ihnen 4 Sek. lang alle 1 Sek. 575632 körperlichen Schaden zufügt und den Schaden der Bestie für 12 Sek. um 10% erhöht. Ignoriert Rüstung.\n\nDie Opfer erleiden zusätzlich 12 Sek. lang alle 1 Sek. 230253 körperlichen Blutungsschaden. Dieser Effekt ist stapelbar." }
entries[433829] = { ["name"] = "Quellfrost", ["text"] = "110 Meter Reichweite\nSofort\nVerleiht Euren Fähigkeiten die Macht der Kugel und gewährt 50 Aufladungen von 'Gefrorene Quelle'. Wenn Ihr Schaden verursacht, wird eine Aufladung verbraucht, die 23 zusätzlichen Frostschaden verursacht sowie Gegner mit 'Quellfrost' belegt, um die Bewegungsgeschwindigkeit von Gegnern um 2% pro Stapel zu verringern.\n\nWenn 'Gefrorene Quelle' vollständig verbraucht wurde, erleiden alle Ziele, die mit 'Quellfrost' belegt sind, 76 Frostschaden pro Stapel, aufgeteilt auf alle Ziele in der Nähe." }
entries[433830] = { ["name"] = "Zerschmettern", ["text"] = "110 Meter Reichweite\nSofort\nVerleiht Euren Fähigkeiten die Macht der Kugel und gewährt 50 Aufladungen von 'Gefrorene Quelle'. Wenn Ihr Schaden verursacht, wird eine Aufladung verbraucht, die 23 zusätzlichen Frostschaden verursacht sowie Gegner mit 'Quellfrost' belegt, um die Bewegungsgeschwindigkeit von Gegnern um 2% pro Stapel zu verringern.\n\nWenn 'Gefrorene Quelle' vollständig verbraucht wurde, erleiden alle Ziele, die mit 'Quellfrost' belegt sind, 76 Frostschaden pro Stapel, aufgeteilt auf alle Ziele in der Nähe." }
entries[433831] = { ["name"] = "Traumwoge", ["text"] = "Gleichgewicht\n'Naturgewalt' verleiht 3 Ladungen von 'Traumeruption', wodurch Euer nächster Einsatz von 'Zorn' oder 'Sternenfeuer' auf dem Ziel explodiert und Gegnern in der Nähe [(318% der Angriffskraft) * 1.04] Naturschaden zufügt. Der Schaden wird bei mehr als 5 Zielen verringert.\n\nWiederherstellung\nDurch 'Hainwächter' generiert Eure nächste gezielte Heilung 2 Traumblüten in der Nähe des Ziels, die bis zu 3 Verbündete in der Nähe um (120% der Zaubermacht) heilen. Bis zu 3-mal stapelbar." }
