entries[433869] = { ["name"] = "Phasenklingen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSikran markiert Spielcharaktere, springt zu den einzelnen markierten Zielen und fügt jedem auf seinem Weg 3741605 körperlichen Schaden zu.\n\nZusätzlich wird die erhaltene Heilung betroffener Spielercharaktere um 50% verringert und sie erleiden 20 Sek. lang alle 2 Sek. 474896 zusätzlichen Schattenschaden.\n\nMarkierte Ziele hinterlassen ein ' Kosmisches Simulakrum ', wenn sie getroffen werden." }
