entries[433895] = { ["name"] = "Vampirstoß", ["text"] = "1 Rune / -10 Runenmacht Nahkampfreichweite\nSofort\nUnheilig\nEin 'Vampirstoß', der (114.4% der Angriffskraft) Schattenschaden verursacht und Euch um 1% Eurer maximalen Gesundheit heilt.\n\nGewährt Euch außerdem 20 Sek. lang 'Essenz der Blutkönigin'.\n\nBlut, Frost\nEin 'Vampirstoß', der (75.5885% der Angriffskraft) Schattenschaden verursacht und Euch um 2% Eurer maximalen Gesundheit heilt.\n\nGewährt Euch außerdem 20 Sek. lang 'Essenz der Blutkönigin'." }
