entries[433899] = { ["name"] = "Vampirstoß", ["text"] = "Sofort\nBlut\nEure Einsätze von 'Todesmantel' und 'Todesstoß' haben eine Chance von 25%, Euren nächsten Einsatz von 'Herzstoß' in 'Vampirstoß' zu verwandeln.\n\n'Vampirstoß' heilt Euch um 1% Eurer maximalen Gesundheit und gewährt Euch 'Essenz der Blutkönigin', die Euer Tempo 20 Sek. lang um 1.0% erhöht, bis maximal 5.0%.\n\nUnheilig\nEure Einsätze von 'Todesmantel', 'Epidemie' und 'Todesstoß' haben eine Chance von 25%, Euren nächsten Einsatz von in 'Vampirstoß' zu verwandeln.\n\n'Vampirstoß' heilt Euch um 2% Eurer maximalen Gesundheit und gewährt Euch 'Essenz der Blutkönigin', die Euer Tempo 20 Sek. lang um 1.0% erhöht, bis maximal 5.0%." }
