entries[434064] = { ["name"] = "Granyths robuste Schuppe", ["text"] = "Sofort 2 min Abklingzeit\nVerringert den erlittenen Schaden 20 Sek. lang um 75% oder bis 12268 Schaden absorbiert wurden. Bei aktivem Schild ist Eure Rüstung um 107 erhöht und wird um weitere 5 erhöht, wenn Ihr einen Treffer erleidet. Bis zu 20-mal stapelbar. Der Schild explodiert, wenn er durchbrochen wird, und verursacht dabei 2683 körperlichen Schaden, der unter allen Gegnern in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich für jeden getroffenen Gegner, bis zu einem Maximum von 5 Gegnern.\n(100ms Abklingzeit)" }
