entries[434137] = { ["name"] = "Giftiger Strahl", ["text"] = "60 Meter Reichweite\nWirken in 3 sek.\nDer Zaubernde entfesselt einen Schwall tödlichen Gifts und fügt damit allen Spielercharaktere 12 Sek. lang alle 1 Sek. 909169 Naturschaden zu.\n\nDer Zaubernde kanalisiert anschließend 9 Sek. lang und lässt dabei Giftkügelchen herabregnen, die Spielercharakteren innerhalb von 3 Metern um die Einschlagsorte 7273348 Naturschaden zufügen." }
