entries[434151] = { ["name"] = "Schrecken entfachen", ["text"] = "Blut\n'Vampirstoß' und 'Herzstoß' lassen Eure Ziele 15 Sek. lang 1% mehr Schattenschaden erleiden, bis zu 5%.\n\n'Vampirstoß' profitiert von 'Schrecken entfachen' bei 400% Effektivität.\n\nUnheilig\n'Vampirstoß' und lassen Eure Ziele 15 Sek. lang 1% mehr Schattenschaden erleiden, bis zu 5%.\n\n'Vampirstoß' profitiert von 'Schrecken entfachen' bei 400% Effektivität." }
entries[434152] = { ["name"] = "Gabe der San'layn", ["text"] = "Unheilig\nWährend 'Dunkle Transformation' aktiv ist, erhaltet Ihr 'Gabe der San'layn'.\n\n'Gabe der San'layn' erhöht die Effektivität Eurer 'Essenz der Blutkönigin' um 100% und ersetzt Euren Zauber für die Dauer durch 'Vampirstoß'.\n\nBlut\nWährend 'Tanzende Runenwaffe' aktiv ist, erhaltet Ihr 'Gabe der San'layn'.\n\n'Gabe der San'layn' erhöht die Effektivität Eurer 'Essenz der Blutkönigin' um 200% und ersetzt Euren Zauber 'Herzstoß' für die Dauer durch 'Vampirstoß'." }
entries[434153] = { ["name"] = "Gabe der San'layn", ["text"] = "Sofort\nUnheilig\nWährend 'Dunkle Transformation' aktiv ist, erhaltet Ihr 'Gabe der San'layn'.\n\n'Gabe der San'layn' erhöht die Effektivität Eurer 'Essenz der Blutkönigin' um 100% und ersetzt Euren Zauber für die Dauer durch 'Vampirstoß'.\n\nBlut\nWährend 'Tanzende Runenwaffe' aktiv ist, erhaltet Ihr 'Gabe der San'layn'.\n\n'Gabe der San'layn' erhöht die Effektivität Eurer 'Essenz der Blutkönigin' um 200% und ersetzt Euren Zauber 'Herzstoß' für die Dauer durch 'Vampirstoß'." }
entries[434155] = { ["name"] = "Phasenklingen", ["text"] = "Unbegrenzte Reichweite\nSofort\nSikran markiert Spielcharaktere, springt zu den einzelnen markierten Zielen und fügt jedem auf seinem Weg 3741605 körperlichen Schaden zu.\n\nZusätzlich wird die erhaltene Heilung betroffener Spielercharaktere um 50% verringert und sie erleiden 20 Sek. lang alle 2 Sek. 474896 zusätzlichen Schattenschaden.\n\nMarkierte Ziele hinterlassen ein ' Kosmisches Simulakrum ', wenn sie getroffen werden." }
