entries[434218] = { ["name"] = "Geläutertes Quellwasser", ["text"] = "100 Meter Reichweite\nSofort\nTränkt Euch im Kampf regelmäßig mit besudeltem ursprünglichen Quellwasser, das für 15 Sek. Eure Vielseitigkeit um 23 sowie Eure Bewegungsgeschwindigkeit um 10% verringert.\nWenn Ihr die Unreinheiten des Wassers bannt, kehrt sich der Effekt um und erhöht für 15 Sek. Eure Vielseitigkeit um 96 , Eure Bewegungsgeschwindigkeit um 10% und gewährt allen Verbündeten in der Nähe einen Schild in Höhe von 587 ." }
entries[434219] = { ["name"] = "Papageienleckerlis" }
entries[434220] = { ["name"] = "Macht des Traumes", ["text"] = "Gleichgewicht\n'Kraft der Natur' verleiht einen zusätzlichen Stapel von 'Traumeruption'.\n\nWiederherstellung\nHeilzauber, die mit 'Traumwoge' gewirkt werden, generieren eine zusätzliche 'Traumblüte'." }
entries[434221] = { ["name"] = "Papageienleckerlis", ["text"] = "Unbegrenzte Reichweite\nSofort\nBeschwört einen treuen Papageienfreund, der Euch im Kampf \"unterstützt\"!\n\nDer Papagei versucht, Gegner mit Guano zu verlangsamen. Der Schaden ist eher seelischer statt körperlicher Natur." }
