entries[434225] = { ["name"] = "Pheromone anwenden", ["text"] = "Wirken in 3 sek.\nWendet Pheromone an, damit Ihr auf dem Umbralbasar nicht auffallt." }
entries[434228] = { ["name"] = "Seltsamer Schneemann", ["text"] = "Sofort\nBeschwört einen seltsamen Schneemann, der einen weiten vereisten Bereich erschafft. Gegnerische Piraten geraten ins Rutschen, wenn sie sich darauf bewegen.\n\nDer Zaubernde und seine Verbündeten bleiben davon unbeeinflusst." }
