entries[434237] = { ["name"] = "Blutbestie", ["text"] = "Unbegrenzte Reichweite\nSofort\nErweckt eine Blutbestie, die an Eurer Seite kämpft. Ihr könnt höchstens eine Blutbestie gleichzeitig beschwören. Hält 10 Sek. lang an." }
entries[434240] = { ["name"] = "Tiefenfähigkeit", ["text"] = "Sofort\nEinsetzen, um eine zusätzliche Aktion zu aktivieren, die in einer Tiefe gewährt wurde." }
entries[434242] = { ["name"] = "Blutklumpen" }
