entries[434244] = { ["name"] = "Evakuieren", ["text"] = "15 Meter Reichweite\nWirken in 1.5 sek.\nRuft nach freien Metbrauern, um den Bereich zu evakuieren." }
entries[434245] = { ["name"] = "Evakuieren" }
entries[434246] = { ["name"] = "Das Blut ist Leben", ["text"] = "100 Meter Reichweite\nSofort\nBlut\n'Tanzende Runenwaffe' beschwört eine Blutbestie, die Euren Gegner 10 Sek. lang angreift.\n\nJedes Mal, wenn die Blutbestie angreift, wird ein Teil des verursachten Schadens in ihr gespeichert. Wenn die Blutbestie stirbt, explodiert sie und fügt Gegnern in der Nähe 25% des angesammelten Schadens zu, während sie den Todesritter um denselben Wert heilt. Gibt es mehr als 8 Ziele, wird der verursachte Schaden verringert.\n\nUnheilig\nbeschwört eine Blutbestie, die Euren Gegner 10 Sek. lang angreift.\n\nJedes Mal, wenn die Blutbestie angreift, wird ein Teil des verursachten Schadens in ihr gespeichert. Wenn die Blutbestie stirbt, explodiert sie und fügt Gegnern in der Nähe 15% des angesammelten Schadens zu, während sie den Todesritter um denselben Wert heilt. Gibt es mehr als 8 Ziele, wird der verursachte Schaden verringert." }
entries[434247] = { ["name"] = "Seltsamer Schneemann" }
entries[434249] = { ["name"] = "Kontrolle des Traumes", ["text"] = "Gleichgewicht\nZeit, in der Eure Hauptfähigkeiten verfügbar sind oder maximale Aufladungen erreicht haben, wird von der Abklingzeit dieser Fähigkeit abgezogen, wenn Ihr sie das nächste Mal benutzt, maximal 15 Sek.\n\nBeeinflusst 'Naturgewalt', und 'Konvokation der Geister'.\n\nWiederherstellung\nZeit, in der Eure Hauptfähigkeiten verfügbar sind oder maximale Aufladungen erreicht haben, wird von der Abklingzeit dieser Fähigkeit abgezogen, wenn Ihr sie das nächste Mal benutzt, maximal 15 Sek.\n\nBeeinflusst 'Schnelligkeit der Natur', 'Inkarnation: Baum des Lebens', und 'Konvokation der Geister'." }
entries[434250] = { ["name"] = "Kreatur der Träume" }
entries[434251] = { ["name"] = "Zorn des Urctos", ["text"] = "Sofort\nSchlägt den nächsten Gegner, verursacht 206 körperlichen Schaden und gewährt 1 Stapel ' Aufsteigender Zorn ', wenn Ihr oder ein Verbündeter Schaden erleidet. Ein Stapel gewährt 1 Hauptwert. Bis zu 30-mal stapelbar. Dieser Effekt kann alle 3 Sek. auftreten.\n\nBei 30 Stapeln von ' Aufsteigender Zorn ' erhaltet Ihr 8 Sek. lang ' Zorn des Urctos ', bevor Ihr sie verbraucht. Der Effekt ist eine Gegenmaßnahme gegen alle Treffer und regeneriert alle 1 Sek. 322 Gesundheit.\n\nNur für Tankspezialisierungen gültig.\n(100ms Abklingzeit)" }
entries[434252] = { ["name"] = "Massives Schmettern", ["text"] = "Wirken in 3.2 sek.\nStampft auf den Boden, fügt Gegnern innerhalb von 60 Metern 2909340 Naturschaden zu und betäubt sie für 1 Sek." }
entries[434253] = { ["name"] = "Allerias dunkler Ansturm", ["text"] = "500 Meter Reichweite\nSofort 1.5 sek. Abklingzeit\nBefiehlt dem Schiff, die Geschwindigkeit zu erhöhen." }
entries[434254] = { ["name"] = "Intensität", ["text"] = "Sofort\nErhöht den verursachten Schaden 30 Sek. lang um 10%. Dieser Effekt ist stapelbar." }
entries[434255] = { ["name"] = "Segen der Schmiede", ["text"] = "100 Meter Reichweite\nSofort\nBeim Einsatz eines Segensworts wird ein Abbild eines Naaru an Eure Seite beschworen. Für die nächsten 9 Sek. imitiert der Naaru alle von Euch gewirkten Heilungs- oder Schadenszauber.\n\nWenn ein Abbild bereits beschworen wurde, wird dieses Abbild stattdessen verstärkt." }
entries[434257] = { ["name"] = "Geschenk der Bärenrache" }
entries[434260] = { ["name"] = "Das Blut ist Leben", ["text"] = "Blut\n'Tanzende Runenwaffe' beschwört eine Blutbestie, die Euren Gegner 10 Sek. lang angreift.\n\nJedes Mal, wenn die Blutbestie angreift, wird ein Teil des verursachten Schadens in ihr gespeichert. Wenn die Blutbestie stirbt, explodiert sie und fügt Gegnern in der Nähe 25% des angesammelten Schadens zu, während sie den Todesritter um denselben Wert heilt. Gibt es mehr als 8 Ziele, wird der verursachte Schaden verringert.\n\nUnheilig\nbeschwört eine Blutbestie, die Euren Gegner 10 Sek. lang angreift.\n\nJedes Mal, wenn die Blutbestie angreift, wird ein Teil des verursachten Schadens in ihr gespeichert. Wenn die Blutbestie stirbt, explodiert sie und fügt Gegnern in der Nähe 15% des angesammelten Schadens zu, während sie den Todesritter um denselben Wert heilt. Gibt es mehr als 8 Ziele, wird der verursachte Schaden verringert.\n\n(1s Abklingzeit)" }
entries[434261] = { ["name"] = "Pakt der San'layn", ["text"] = "Blut\nIhr speichert 10% sämtlichen verursachten Schattenschadens, in eurer Blutbestie, der bei ihrer Todesexplosion zusätzlich entfesselt wird.\n\nUnheilig\nIhr speichert 15% sämtlichen verursachten Schattenschadens, in eurer Blutbestie, der bei ihrer Todesexplosion zusätzlich entfesselt wird." }
entries[434263] = { ["name"] = "Blutaroma", ["text"] = "Blut\nEure Zauber 'Todesmantel' und 'Todesstoß' haben eine um 15% höhere Chance, 'Vampirstoß' auszulösen, wenn sie Gegnern mit weniger als 35% Gesundheit Schaden zufügen.\n\nUnheilig\nEure Zauber 'Todesmantel', 'Epidemie' und 'Todesstoß' haben eine um 15% höhere Chance, 'Vampirstoß' auszulösen, wenn sie Gegnern mit weniger als 35% Gesundheit Schaden zufügen." }
entries[434264] = { ["name"] = "Glutbräueruption" }
entries[434266] = { ["name"] = "Fokus wechseln", ["text"] = "500 Meter Reichweite\nSofort 1.5 sek. Abklingzeit\nLegt Euren Fokus auf einen anderen Teil des Schiffs." }
entries[434268] = { ["name"] = "Quakplatsch", ["text"] = "100 Meter Reichweite\nSofort\nVerzaubert eine Zielposition, sodass sie nach einer kurzen Verzögerung explodiert, allen Gegnern innerhalb von 12 Metern Frostschaden zufügt und sie zurückstößt." }
entries[434269] = { ["name"] = "Quakplatsch", ["text"] = "40 Meter Reichweite\nWirken in 2 sek. 12 sek. Abklingzeit\nVerzaubert eine Position, sodass dort nach einer kurzen Verzögerung eine Explosion auftritt, die allen Gegnern innerhalb von 12 Metern Frostschaden zufügt und sie zurückstößt." }
entries[434270] = { ["name"] = "Granyths robuste Schuppe", ["text"] = "Sofort\nVerringert den erlittenen Schaden 20 Sek. lang um 75% oder bis 12268 Schaden absorbiert wurden. Bei aktivem Schild ist Eure Rüstung um 107 erhöht und wird um weitere 5 erhöht, wenn Ihr einen Treffer erleidet. Bis zu 20-mal stapelbar. Der Schild explodiert, wenn er durchbrochen wird, und verursacht dabei 2683 körperlichen Schaden, der unter allen Gegnern in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich für jeden getroffenen Gegner, bis zu einem Maximum von 5 Gegnern." }
