entries[434300] = { ["name"] = "Bombardements", ["text"] = "Verheerung\n'Massendesintegration' markiert Euer Primärziel für die nächsten 6 Sek. zur Vernichtung.\n\nIhr und Eure Verbündeten habt eine Chance, ein 'Bombardement' auszulösen, wenn markierte Ziele angegriffen werden, was [[Quellwert] * 4.75 * (1 + Vielseitigkeit) * Prozentualer Schaden] Vulkanschaden verursacht, die auf alle Gegner in der Nähe aufgeteilt werden.\n\nBewahrung, Verstärkung\n'Masseneruption' markiert Euer Primärziel für die nächsten 6 Sek. zur Vernichtung.\n\nIhr und Eure Verbündeten habt eine Chance, ein 'Bombardement' auszulösen, wenn markierte Ziele angegriffen werden, was [[Quellwert] * 4.75 * (1 + Vielseitigkeit) * Prozentualer Schaden] Vulkanschaden verursacht, die auf alle Gegner in der Nähe aufgeteilt werden.", ["unresolvedValues"] = true }
