entries[434400] = { ["name"] = "Grubenlord beschwören", ["text"] = "Sofort\nZerstörung\nDas Wirken von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' gewährt 'Diabolisches Ritual' für 20 Sek.. Wenn 'Diabolisches Ritual' bereits aktiv ist, wird seine Dauer stattdessen um 1 Sek. verringert.\n\nWenn 'Diabolisches Ritual' abläuft, erhaltet Ihr 'Dämonische Kunst', wodurch Euer nächster Einsatz von 'Chaosblitz', 'Feuerregen' oder 'Schattenbrand' einen Oberanführer, eine Mutter des Chaos oder einen Grubenlord herbeiruft, die einen vernichtenden Angriff gegen Eure Gegner entfesseln.\n\nDämonologie\nDer Verbrauch eines Seelensplitters gewährt Euch für 20 Sek. 'Diabolisches Ritual'. Während 'Diabolisches Ritual' aktiv ist, verringert jeder für einen schadensverursachenden Zauber verbrauchte Seelensplitter dessen Dauer um 1 Sek.\n\nWenn 'Diabolisches Ritual' abläuft, erhaltet Ihr 'Dämonische Kunst', wodurch Euer nächster Einsatz von 'Hand von Gul'dan' einen Oberanführer, eine Mutter des Chaos oder einen Grubenlord herbeiruft, die einen vernichtenden Angriff gegen Eure Gegner entfesseln." }
entries[434401] = { ["name"] = "Walzende Säure", ["text"] = "Sofort\nRasha'nan stößt ein giftiges Gebräu auf markierte Ziele aus, das in Wellen vom Ziel aus in die angegebene Richtung schwappt.\n\nSpielercharaktere, die von der anfänglichen ätzenden Eruption bespritzt werden, erleiden ' Ätzende Benommenheit '.\n\nJeder Spielercharakter, der eine Welle berührt, wird um 50% verlangsamt und wird alle 1 Sek. mit ' Korrosion ' belegt.\n\nDie Wellen verbrennen ' Klebrige Netze ', fügen Spielcharakteren im Umkreis von 5 Metern 7273348 Naturschaden zu und erzeugen ' Säurepfützen '." }
entries[434402] = { ["name"] = "Leerengebunden" }
entries[434404] = { ["name"] = "Teufelssucher", ["text"] = "25 Energie Unbegrenzte Reichweite\nSofort\nEntfesselt einen machtvollen Strahl von Teufelsmagie, der die Seele des gegnerischen Ziels versengt und (320.679% der Zaubermacht) Chaosschaden verursacht." }
entries[434406] = { ["name"] = "Walzende Säure", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan stößt ein giftiges Gebräu auf markierte Ziele aus, das in Wellen vom Ziel aus in die angegebene Richtung schwappt.\n\nSpielercharaktere, die von der anfänglichen ätzenden Eruption bespritzt werden, erleiden ' Ätzende Benommenheit '.\n\nJeder Spielercharakter, der eine Welle berührt, wird um 50% verlangsamt und wird alle 1 Sek. mit ' Korrosion ' belegt.\n\nDie Wellen verbrennen ' Klebrige Netze ', fügen Spielcharakteren im Umkreis von 5 Metern 7273348 Naturschaden zu und erzeugen ' Säurepfützen '." }
entries[434407] = { ["name"] = "Walzende Säure", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nRasha'nan stößt ein giftiges Gebräu auf markierte Ziele aus, das in Wellen vom Ziel aus in die angegebene Richtung schwappt.\n\nSpielercharaktere, die von der anfänglichen ätzenden Eruption bespritzt werden, erleiden ' Ätzende Benommenheit '.\n\nJeder Spielercharakter, der eine Welle berührt, wird um 50% verlangsamt und wird alle 1 Sek. mit ' Korrosion ' belegt.\n\nDie Wellen verbrennen ' Klebrige Netze ', fügen Spielcharakteren im Umkreis von 5 Metern 7273348 Naturschaden zu und erzeugen ' Säurepfützen '." }
entries[434408] = { ["name"] = "Auge des Schwarms", ["text"] = "Kanalisiert (Wirken in 25 sek.)\nWenn Anub'zekt 100 Energie erreicht, ruft er einen riesigen Schwarm herbei, der die Arena umgibt. Spielercharaktere innerhalb des Insektenschwarms erhalten schnell Anwendungen von 'Endloser Schwarm'." }
