entries[435082] = { ["name"] = "Mogudunstfackel", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieses uralte Moguartefakt kontrolliert den in der Luft liegenden Nebel, um aufzusteigen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
