entries[435103] = { ["name"] = "Flinkes Windross", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Windrösser sind ungemein sanft und leicht zu trainieren... wenn man sie fangen kann.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435105] = { ["name"] = "Verfolgungsquest" }
entries[435107] = { ["name"] = "Waldwindross", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Das Fell dieses Windrosses passt nicht nur farblich zu seiner bewaldeten Heimat, für gewöhnlich ist es auch mit Rindenstücken und Blättern gespickt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435108] = { ["name"] = "Tagsturmwindross", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Wenn ein Blitz die Sonne trifft, soll ein gleißendes Biest in roter Rüstung aus den Himmeln herabsteigen. Das Tagsturmwindross hat von dieser Legende noch nie gehört und war schon immer hier.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435109] = { ["name"] = "Gefiederter Windwellenreiter", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Vor dem Aufsteigen die aktuelle Windstärke und Höhe überprüfen. Bäume und andere hohe Objekte vermeiden. Beschädigte Drachen sind von der Rückgabe ausgeschlossen.\" - Bedienungsanleitung des Windwellenreiters\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435110] = { ["name"] = "Extrahieren" }
entries[435114] = { ["name"] = "Kein Besitzer" }
entries[435115] = { ["name"] = "Qilenwächter", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Als Quan der Unerbittliche im Kampf fiel, harrten seine treuen Hunde seiner Rückkehr. Jahrtausende später warten sie noch immer geduldig.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435118] = { ["name"] = "Marmorqilen", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Von einem Mogumagier erschaffen, der seinem Lieblingsstein Leben einhauchte.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435119] = { ["name"] = "Netzwirbel", ["text"] = "300 Meter Reichweite\nSofort\nUlgrax speit Spinnweben auf einen Spielercharakter und alle Verbündeten im Umkreis von 10 Metern und verursacht 17331401 Naturschaden, die gleichmäßig auf alle Spielercharaktere aufgeteilt werden, und fesselt sie an Ulgrax.\n\nGefesselte Spielercharaktere erleiden alle 2 Sek. 575632 Naturschaden und werden zu Ulgrax gezogen. Die Stärke, mit der Ulgrax die Spielercharaktere anzieht, wird für jeden gefesselten Spielercharakter verringert." }
entries[435123] = { ["name"] = "Goldener Reitkranich", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein Kaiser soll einst eine große Summe für einen goldenen Kranich bezahlt haben. Als er erkannte, dass der Kranich lediglich seine Farbe mit dem wertvollen Metall teilte, verkroch er sich voller Scham eine Woche in seinem Schlafgemach.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435124] = { ["name"] = "Luxuriöser Reitkranich", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Ein majestätischer Vogel, aber ziemlich wählerisch, was sein Futter angeht.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435125] = { ["name"] = "Tropischer Reitkranich", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Bewohner des Jadewalds nutzt seine Färbung zur Tarnung.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435126] = { ["name"] = "Silberner Reitkranich", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser große Vogel gehört zu den anmutigsten und elegantesten Kranichen, mehr noch als der Bronzekranich, wenn auch nicht so sehr wie der Goldene.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435127] = { ["name"] = "Rosenreitkranich", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser farbenprächtige Vogel wird oft mit einem Flamingo oder Marabu verwechselt.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435128] = { ["name"] = "Bleicher Reitkranich", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Und ich sah, und siehe, ein fahler... Kranich?\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435129] = { ["name"] = "Gut gewürzt", ["text"] = "100 Meter Reichweite\nSofort\nDer Koch würzt alle Spielercharaktere mit Salz, was alle 1.5 Sek. 4 körperlichen Schaden verursacht und sämtlichen erlittenen Schaden um 10% erhöht. Hält 9 Sek. lang an.\n\nDieser Effekt ist stapelbar." }
entries[435130] = { ["name"] = "Gut gewürzt", ["text"] = "100 Meter Reichweite\nSofort\nDer Koch würzt alle Spielercharaktere mit Salz, was alle 1.5 Sek. 4 körperlichen Schaden verursacht und sämtlichen erlittenen Schaden um 10% erhöht. Hält 9 Sek. lang an.\n\nDieser Effekt ist stapelbar." }
entries[435131] = { ["name"] = "Verschneite Reitziege", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Bergziegen des Kun-Lai-Gipfels sind bekannt dafür, auf der Suche nach Kafabohnen und Salzlecksteinen selbst die höchsten Wipfel zu erklimmen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435132] = { ["name"] = "Esst mich!" }
entries[435133] = { ["name"] = "Kleine rote Reitziege", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Was dieser Ziege an Größe fehlt, macht sie mit Sturheit wett.\"\nWeltereignis:\nMists of Pandaria: Remix" }
entries[435134] = { ["name"] = "Esst mich!" }
entries[435135] = { ["name"] = "Köstlich" }
entries[435136] = { ["name"] = "Giftpeitscher", ["text"] = "20 Meter Reichweite\nWirken in 2 sek.\nUlgrax schleudert Gift auf alle Spielercharaktere, das beim Einschlag 1726895 Naturschaden sowie 6 Sek. lang alle 1 Sek. 978574 zusätzlichen Naturschaden verursacht." }
entries[435138] = { ["name"] = "Verdauungssäure", ["text"] = "300 Meter Reichweite\nWirken in 2 sek.\nUlgrax speit Verdauungssäure auf mehrere Spielercharaktere, die 6 Sek. lang alle 2 Sek. 1726895 Naturschaden verursacht.\n\nWenn der Effekt entfernt wird, bricht Gift aus der Haut des Opfers aus, das allen Spielercharakteren innerhalb von 7 Metern 1151263 Naturschaden zufügt und jegliche Spinnweben zersetzt, die von ' Pirscherspinnweben ' hinterlassen wurden." }
entries[435140] = { ["name"] = "In die Maschine - Verlassen" }
entries[435141] = { ["name"] = "Pakt des Todesbringers", ["text"] = "Wenn Ihr Schaden entsprechend 2% Eurer maximalen Gesundheit erleidet, wirkt Ihr sofort 'Todespakt' mit 25% Effektivität. Kann nur alle 50 Min. auftreten.\n\nWenn ein 'Mal des Schnitters' explodiert, wird die Abklingzeit dieses Effekts und von 'Dunkler Pakt' um 25 Sek. verringert." }
entries[435142] = { ["name"] = "In die Maschine - Verlassen - Teleportieren" }
entries[435143] = { ["name"] = "Phasenklingen", ["text"] = "Unbegrenzte Reichweite\nKanalisiert (Wirken in 1.5 sek.)\nSikran markiert Spielcharaktere, springt zu den einzelnen markierten Zielen und fügt jedem auf seinem Weg 3741605 körperlichen Schaden zu.\n\nZusätzlich wird die erhaltene Heilung betroffener Spielercharaktere um 50% verringert und sie erleiden 20 Sek. lang alle 2 Sek. 474896 zusätzlichen Schattenschaden.\n\nMarkierte Ziele hinterlassen ein ' Kosmisches Simulakrum ', wenn sie getroffen werden." }
entries[435144] = { ["name"] = "Pfählende Splitter", ["text"] = "Jedes Mal, wenn Euer durch 'Permafrost' erzeugter Schild Schaden nimmt, besteht die Chance, dass eisige Splitter auf Gegner in der Nähe gefeuert werden, die (5% der Angriffskraft) Frostschaden verursachen und der Schaden, den Euch Gegner zufügen, wird für 5 Sek. um 5% reduziert." }
entries[435145] = { ["name"] = "Blutiger Himmelskreischer", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Dieser Dinosaurier trägt noch immer den Zorn seiner Vorfahren von der Zandalariinvasion in sich.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435146] = { ["name"] = "Nachtpterrorschwinge", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die Gelehrten erkennen im fürchterlichen Kreischen dieser Kreatur ein \"Fürchtet mich, ich bin die Nacht!\"\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435147] = { ["name"] = "Jadepterrordax", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Das bevorzugte Reittier der Zandalari ist ein großartiger Sänger, zumindest denkt es das.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435148] = { ["name"] = "Lodernder Angriff", ["text"] = "8 Meter Reichweite\nWirken in 1.5 sek.\nVerursacht 4848899 Heiligschaden sowie zusätzlich 10 Sek. lang alle 1 Sek. 484890 Heiligschaden." }
entries[435149] = { ["name"] = "Kobaltkoloss", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Die einstige Bergbau- und Holzfällermaschine nahm schnell chaotische Züge an, als den Ingenieuren der Gedanke kam, ob man sie nicht noch etwas cooler machen könnte.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435150] = { ["name"] = "Teufelseisenkoloss", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Diese Kriegsmaschine wurde aus einer Zeitlinie gestohlen, in der Garrosh Höllschrei sich der Brennenden Legion anschloss. Unnötig zu erwähnen, dass von dieser Zeitlinie nicht mehr viel übrig ist.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435151] = { ["name"] = "Auge des Schwarms", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Anub'zekt 100 Energie erreicht, ruft er einen riesigen Schwarm herbei, der die Arena umgibt. Spielercharaktere innerhalb des Insektenschwarms erhalten schnell Anwendungen von 'Endloser Schwarm'." }
entries[435152] = { ["name"] = "Verdauungssäure", ["text"] = "300 Meter Reichweite\nSofort\nUlgrax speit Verdauungssäure auf mehrere Spielercharaktere, die 6 Sek. lang alle 2 Sek. 1726895 Naturschaden verursacht.\n\nWenn der Effekt entfernt wird, bricht Gift aus der Haut des Opfers aus, das allen Spielercharakteren innerhalb von 7 Metern 1151263 Naturschaden zufügt und jegliche Spinnweben zersetzt, die von ' Pirscherspinnweben ' hinterlassen wurden." }
entries[435153] = { ["name"] = "Violetter Shado-Pan-Reittiger", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Wollt Ihr einen Tiger wecken, nehmt einen langen Stock. Oder noch besser: Schickt einen Freund, den Tiger zu wecken.\" - Pandarensprichwort\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435155] = { ["name"] = "Feuerhonig halten" }
entries[435156] = { ["name"] = "Lichtausstoß", ["text"] = "40 Meter Reichweite\nSofort\nEine Lichtexplosion fährt aus dem Körper des Auferstandenen und fügt allen Spielercharakteren innerhalb von 60 Metern 1212225 Heiligschaden zu." }
entries[435160] = { ["name"] = "Flussläufermushan", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Das Mushan ist eine gierige Bestie. Es kann zwar gezähmt werden, doch wird es ein zweites, drittes, ja sogar viertes Frühstück an jedem Tag verlangen.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435161] = { ["name"] = "Fahles Mushan", ["text"] = "Wirken in 1.5 sek.\nBeschwört dieses Reittier oder gibt es wieder frei.\n\"Das fahle Mushan ist das köstlichste seiner Art, allerdings wird es nicht gern daran erinnert.\"\nWeltereignis:\nWoW Remix: Mists of Pandaria" }
entries[435162] = { ["name"] = "Tödlicher Schuss", ["text"] = "40 Meter Reichweite\nSofort 1 min Abklingzeit\nBrann erledigt verwundete Ziele, indem er Gegner mit weniger als 30% Gesundheit hinrichtet.\n\nDie Gesundheitsschwelle für diesen Effekt wird bei Bosskreaturen auf 5% verringert." }
