entries[435203] = { ["name"] = "Donnerknall", ["text"] = "100 Meter Reichweite\nSofort\nFuror\nÜberzieht alle Gegner innerhalb von 8 Metern mit (49.1% der Angriffskraft) körperlichem Schaden und verringert ihre Bewegungsgeschwindigkeit 10 Sek. lang um 20%. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n[\nErzeugt 0 Wut. ]\nWaffen\nÜberzieht alle Gegner innerhalb von 8 Metern mit (49.1% der Angriffskraft) körperlichem Schaden und verringert ihre Bewegungsgeschwindigkeit 10 Sek. lang um 20%. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n[\nErzeugt 0 Wut. ]\nFalls Ihr über 'Verwunden' verfügt, belegt 'Donnerknall' 5 Ziele in der Nähe mit 'Verwunden'.\n\nSchutz\nÜberzieht alle Gegner innerhalb von 8 Metern mit (49.1% der Angriffskraft) körperlichem Schaden und verringert ihre Bewegungsgeschwindigkeit 10 Sek. lang um 20%. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n[\nErzeugt 0 Wut. ]\nFalls Ihr über 'Verwunden' verfügt, belegt 'Donnerknall' 5 Ziele in der Nähe mit 'Verwunden'." }
entries[435208] = { ["name"] = "Retten", ["text"] = "5 Meter Reichweite\nWirken in 1.5 sek.\nRettet einen verletzten Irdenen." }
entries[435211] = { ["name"] = "Runenschaltung" }
entries[435214] = { ["name"] = "Blitzheilung" }
entries[435215] = { ["name"] = "Kein Entkommen", ["text"] = "Wenn 'Mal des Schnitters' explodiert, wird die Abklingzeit von 'Griff des Schnitters' für jeden Stapel 'Mal des Schnitters', mit dem das Ziel belegt ist, um 1 Sek. reduziert.\n\nZusätzlich explodiert 'Mal des Schnitters' zu 'Seelenernter', wenn die Gesundheit des Ziels unter 35% fällt." }
