entries[435222] = { ["name"] = "Donnerexplosion", ["text"] = "30 Wut\nSofort 6 sek. Abklingzeit\nÜberzieht alle Gegner innerhalb von 8 Metern mit (54.3356% der Angriffskraft) Sturmschlagschaden [ Vom Donner gerührt : macht sie 6 Sek. lang bewegungsunfähig ] und verringert ihre Bewegungsgeschwindigkeit 10 Sek. lang um 20%. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu.\n[\nErzeugt 2 Wut. ]" }
entries[435227] = { ["name"] = "Rufen", ["text"] = "5 Meter Reichweite\nWirken in 2 sek. 5 sek. Abklingzeit\nRuft Moira herbei, um Furchtbrecher zum Abschirmen irdener Verweigerer zu nutzen." }
