entries[435389] = { ["name"] = "Gedenkstein", ["text"] = "Wirken in 2 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nNullstein (4), Weißer Rosenstrauß , Bismut (50), Aqirit (30), Eisenklauenerz (30), Marmorstein (200)\nVerkäufer:\nLyrendal\nZone:\nDornogal\nKosten:\n150\n\nGedenkstein\nSpielzeug\nBenutzen: Bereitet einem gefallenen Spielercharakter ein respektvolles Begräbnis. (5 Min Abklingzeit)\n\"Seid immer vorbereitet.\"" }
entries[435391] = { ["name"] = "Verschönerungsiris", ["text"] = "Wirken in 2 sek.\nTools: Juwelierswerkzeuge\nReagenzien:\nZermahlene Edelsteine (40), Invertiertes Prisma (5)\nBeute von:\nWeltkreaturen\n\nVerschönerungsiris\nSpielzeug\nBenutzen: Fokussiert einen farbenfrohen Lichtstrahl durch einen Edelstein auf ein hilfloses Kleintier. (10 Min Abklingzeit)\n\"Die Welt ist grässlich, aber das heißt nicht, dass sie auch hässlich sein muss.\"" }
